import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`apartment-search`,heroTitle:`Find your perfect apartment in minutes`,heroSubtitle:`Perplexity Computer searches listings, compares prices and commutes, and builds your shortlist — automatically.`,inputUrlCta:`Find my apartment`,inputUrlPlaceholder:`City or neighborhood (e.g. SF Mission District)`,inputUrlPrefill:`Use the following location and criteria: {url}. Conduct a comprehensive apartment search across major rental platforms for that area. 1) Find 15-20 available apartments matching the criteria, including rent price, square footage, bedroom/bathroom count, move-in date, pet policy, and amenities. 2) For each listing, calculate commute times to the nearest transit stops and major employment hubs. 3) Research the neighborhood — walk score, crime stats, nearby grocery stores, restaurants, and parks. 4) Compare total monthly cost including utilities estimates, parking, and typical renter's insurance for each area. 5) Score each apartment on value, location, and livability. 6) Deliver a ranked shortlist with the top 10 apartments, a side-by-side comparison table, and a summary recommendation explaining the best options and tradeoffs.`,heroOverlaySteps:[`Analyzing your location preferences and rental criteria`,`Searching listings across major rental platforms`,`Comparing prices, commutes, and neighborhood quality`,`Ranked shortlist with side-by-side comparisons — ready to tour`],generatingSteps:[`Visiting {url} to extract your location, budget, and apartment preferences`,`Designing an agent to search and compare listings across rental platforms`,`Configuring commute calculations, neighborhood scoring, and cost analysis`,`Setting up your ranked shortlist with side-by-side comparisons`],featureSectionTitle:`From wishlist to shortlist`,featureCardTitles:[`Connects to your planning tools`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Trello — Computer organizes your apartment shortlist and comparison data in the tools you already use.`,`Ranked apartment shortlist. Side-by-side comparison table. Commute time breakdowns. Neighborhood scores. Total monthly cost estimates. Summary recommendation with tradeoffs.`],capabilitySectionTitle:`Your apartment search, on autopilot`,capabilitySectionSubtitle:`Share your criteria, step away, come back to a curated shortlist.`,capabilityCards:[{title:`Listing Discovery`,description:`Computer can search across major rental platforms — filtering by price, size, location, pet policy, and move-in date to surface every option that fits.`},{title:`Commute Analysis`,description:`Computer can calculate commute times by transit, car, and bike to your workplace — and flag listings with the best transportation access.`},{title:`Neighborhood Research`,description:`Computer can pull walk scores, crime stats, grocery access, parks, and nightlife data — so you know the neighborhood before you visit.`},{title:`Connect Your Tools`,description:`Computer can push your shortlist to Google Sheets, Notion, Trello, and Google Drive — build workflows across your entire apartment search stack.`},{title:`Remember & Refine`,description:`Computer can remember your preferences, rejected listings, and favorite neighborhoods across sessions — so every search gets sharper.`},{title:`Monitor & Alert`,description:`Computer can re-check listings daily and alert you when new apartments match your criteria or prices drop on your shortlist.`}]});export{t as default};
